        public static void Preload()
        {
            if (frames != null)
                return;
            frames = new Sprite[UniqueSpriteCount];
            for (int i = 0; i < frames.Length; i++)
                frames[i] = IndividualArt.Sprite(Root + "/" + i.ToString("D5"));
        }
        public static int Profile(WeaponFamily f) => f == WeaponFamily.Staff || f == WeaponFamily.Orb ? 4 : f == WeaponFamily.Dagger ? 0 : f == WeaponFamily.Longsword || f == WeaponFamily.Katana || f == WeaponFamily.Spear ? 1 : f == WeaponFamily.Mace || f == WeaponFamily.Greatsword ? 2 : f == WeaponFamily.Bow ? 3 : f == WeaponFamily.Pistol ? 4 : 5;
        public static Sprite Sample(int profile, int d, int variant, int key, out Vector2 h, out bool b)
        {
            Preload();
            int slot = ((Mathf.Clamp(profile, 0, 5) * 8 + Mathf.Clamp(d, 0, 7)) * 16 + Mathf.Clamp(variant, 0, 15)) * 9 + Mathf.Clamp(key, 0, 8);
            h = Hands[slot];
            b = Behind[slot];
            return frames[Cells[slot]];
        }
        public static float Angle(int profile, float progress, Vector2 aim) => (profile == 3 ? Mathf.DeltaAngle(Mathf.Atan2(aim.y, aim.x) * Mathf.Rad2Deg, aim.x < -.1f || aim.y < -.9f ? 0 : 180) : (profile == 0 ? -10 : profile == 1 ? 20 : profile == 2 ? 38 : 0) * (aim.x < 0 ? -1 : 1)) * Mathf.SmoothStep(0, 1, progress);
    }
